window.docContents[79].resolve({"/Basic-Types/Strings/#Lean-__________________--Basic-Types--Strings--API-Reference--String-Slices--API-Reference--Copying":{"contents":"Creates a String from a String.Slice by copying the bytes.\n\n","context":"Lean 中文参考手册\u0009Basic Types\u0009Strings\u0009API Reference\u0009String Slices\u0009API Reference","header":"20.8.4.11.1.1. Copying","id":"/Basic-Types/Strings/#Lean-__________________--Basic-Types--Strings--API-Reference--String-Slices--API-Reference--Copying"},"/Basic-Types/The-Empty-Type/#Lean-__________________--Basic-Types--The-Empty-Type--API-Reference":{"contents":"Empty.elim : Empty → C says that a value of any type can be constructed from\nEmpty. This can be thought of as a compiler-checked assertion that a code path is unreachable.\n\nPEmpty.elim : Empty → C says that a value of any type can be constructed from\nPEmpty. This can be thought of as a compiler-checked assertion that a code path is unreachable.\n\n","context":"Lean 中文参考手册\u0009Basic Types\u0009The Empty Type","header":"20.10.1. API Reference","id":"/Basic-Types/The-Empty-Type/#Lean-__________________--Basic-Types--The-Empty-Type--API-Reference"},"/releases/v4.29.0/#Lean-__________________--Release-Notes--Lean-4___29___0-_LPAR_2026-03-27_RPAR_--Highlights--Changes-to-Instance-and-Reducibility-Handling--Migration-guide":{"contents":"Any projects wanting to postpone dealing with the adaptations required by the changes to transparency level bumps can\nsimply use set_option backward.isDefEq.respectTransparency false.\n\nThis can be set on a project-wide level in your lakefile.toml:\n\n[leanOptions]\nbackward.isDefEq.respectTransparency = false\n\n\nHowever we encourage you to instead localize the option in the files that need it,\nor even on individual declarations using set_option backward.isDefEq.respectTransparency false in ....\nThis makes it easier to start identifying the definitional abuse problems in your code.\n\nIf your project is downstream of Mathlib, you may find the following two scripts useful:\n\n* scripts/add_set_option.py (available in .lake/packages/mathlib/scripts/add_set_option.py if you have Mathlib as a dependency)\n  which tries compiling your project, and automatically wrapping any failing declaration with set_option backward.isDefEq.respectTransparency false in ...,\n  in those cases where doing so resolves the failure.* scripts/rm_set_option.py, which compiles your project and identifies all occurrences of set_option backward.isDefEq.respectTransparency false in ... which can be removed without causing a failure (in that same declaration).\n  This may happen because of earlier changes which resolve the definitional abuse problem.\n\nThese scripts can also be copied out of Mathlib and run on any project.\n\nAgain, when downstream of Mathlib you may also use the experimental #defeq_abuse in ... command,\nwhich attempts to identify and explain, or at least give clues to, the underlying definitional abuse problem that\nmay explain why a declaration currently needs set_option backward.isDefEq.respectTransparency false in ....\nWe encourage users to report problems with this command on the Zulip,\nand we hope that as this diagnostic command stabilizes we will be able to make it available as part of a future Lean toolchain.\n\nYou are encouraged to review the construction of instances for all default transparency type synonyms in your project.\nWhere possible, you should use the deriving handler, or the new inferInstanceAs elaborator,\nrather than writing term mode constructions which require unfolding the type synonym in order to typecheck.\nThe inferInstanceAs command now requires an expected type.\nIf you encounter errors where inferInstanceAs now gives an error because an expected type was not provided,\nyou may find that you should simply be using inferInstance instead.\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.29.0 (2026-03-27)\u0009Highlights\u0009Changes to Instance and Reducibility Handling","header":"Migration guide","id":"/releases/v4.29.0/#Lean-__________________--Release-Notes--Lean-4___29___0-_LPAR_2026-03-27_RPAR_--Highlights--Changes-to-Instance-and-Reducibility-Handling--Migration-guide"},"/releases/v4.32.0/#Lean-__________________--Release-Notes--Lean-4___32___0-_LPAR_2026-07-13_RPAR_--Highlights--Lake___-Linter-Overhaul-and-Cache-Improvements":{"contents":"\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.32.0 (2026-07-13)\u0009Highlights","header":"Lake: Linter Overhaul and Cache Improvements","id":"/releases/v4.32.0/#Lean-__________________--Release-Notes--Lean-4___32___0-_LPAR_2026-07-13_RPAR_--Highlights--Lake___-Linter-Overhaul-and-Cache-Improvements"}});